  if (!raw.length) throw new Error('logo svg has no filled shapes');
  /* brand blue = the paths whose own fill is clearly blue. images/logo.svg carries no colours at all (every path is the default black),
     so then the blue piece is the one that holds the top of the mark: the upper-left leaf of the client's artwork. */
  const blueCol = c => !!c && (c.b - c.r) > 0.2 && c.b > 0.3;
  let blue = raw.map(r => blueCol(r.color));
