      for (const p of outer) { bx0 = Math.min(bx0, p.x); bx1 = Math.max(bx1, p.x); by0 = Math.min(by0, p.y); by1 = Math.max(by1, p.y); }
      return { outer, holes: s.holes.map(tf).filter(r => r.length > 2), blue: blue[i], box: [bx0, by0, bx1, by1] };
