const OUTLINES = new Map();
function getOutline(THREE, SVGLoader, svgUrl, small, cast = false) {
  const key = svgUrl + (small ? '|s' : '') + (cast ? '|cast' : '');
  if (!OUTLINES.has(key)) {
    OUTLINES.set(key, (async () => {
      const text = await (await fetch(svgUrl)).text();
      const outline = parseOutline(THREE, SVGLoader, text, svgUrl.includes('text_logo3.svg') ? 3 : svgUrl.includes('text_logo2.svg') ? 2 : 0);
      const cell = small ? 0.0055 : 0.0034;
      outline.fields = [];
      if (!cast) for (const sh of outline.shapes) { const f = await buildField(sh, cell); f.blue = sh.blue; f.box = sh.box; outline.fields.push(f); }
      return outline;
    })().catch(e => { OUTLINES.delete(key); throw e; }));
  }
  return OUTLINES.get(key);
}

/* ============================================================================================================
   4. Built-in environment: dusk sky + lake + soft boxes (PMREM)
   ============================================================================================================ */
function makeFallbackEnvironment(THREE, renderer) {
  const scene = new THREE.Scene();
  const mat = new THREE.ShaderMaterial({
    side: THREE.BackSide, depthWrite: false,
    vertexShader: 'varying vec3 vDir; void main(){ vDir = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }',
    fragmentShader: /* glsl */`
      varying vec3 vDir;
      vec3 lin(vec3 c){ return pow(c, vec3(2.2)); }
      float box(vec3 d, vec3 c, float sx, float sy, float soft){
        vec3 up = vec3(0.0, 1.0, 0.0);
        vec3 r = normalize(cross(up, c)); vec3 u = cross(c, r);
        float f = dot(d, c);
        if (f < 0.0) return 0.0;
        vec2 p = vec2(dot(d, r), dot(d, u)) / max(f, 0.001);
        vec2 q = abs(p) - vec2(sx, sy);
        float e = max(q.x, q.y);
        return 1.0 - smoothstep(-soft, soft, e);
      }
      void main(){
        vec3 d = normalize(vDir);
        float h = d.y;
        vec3 zen = vec3(0.17, 0.27, 0.52), mid = vec3(0.50, 0.58, 0.74), hor = vec3(0.80, 0.80, 0.86), wat = vec3(0.36, 0.46, 0.62), deep = vec3(0.15, 0.23, 0.36);
        vec3 c;
        if (h >= 0.0) { c = mix(hor, mid, smoothstep(0.0, 0.28, h)); c = mix(c, zen, smoothstep(0.2, 0.95, h)); }
        else { c = mix(hor * 0.85, wat, smoothstep(0.0, 0.14, -h)); c = mix(c, deep, smoothstep(0.1, 0.9, -h)); }
        c = lin(c);
        vec3 sunDir = normalize(vec3(-0.62, 0.30, -0.72));
        float sd = max(dot(d, sunDir), 0.0);
        c += lin(vec3(1.0, 0.78, 0.58)) * (pow(sd, 6.0) * 0.55 + pow(sd, 90.0) * 2.0 + pow(sd, 900.0) * 14.0);
        /* soft boxes: a big overhead sky panel, a tall strip on each side and a low warm kicker */
        c += lin(vec3(0.88, 0.93, 1.0)) * 2.6 * box(d, normalize(vec3(0.15, 0.95, 0.35)), 0.55, 0.45, 0.25);
        c += lin(vec3(0.93, 0.97, 1.0)) * 3.4 * box(d, normalize(vec3(-0.95, 0.12, 0.38)), 0.10, 0.62, 0.05);
        c += lin(vec3(0.80, 0.90, 1.0)) * 2.3 * box(d, normalize(vec3(0.92, 0.18, 0.40)), 0.08, 0.55, 0.05);
        c += lin(vec3(1.0, 0.88, 0.76)) * 1.4 * box(d, normalize(vec3(-0.35, -0.15, 0.93)), 0.5, 0.12, 0.12);
        c += lin(vec3(0.75, 0.86, 1.0)) * 0.9 * box(d, normalize(vec3(0.0, 0.18, 1.0)), 0.7, 0.34, 0.2);
        gl_FragColor = vec4(c, 1.0);
      }`
  });
  const dome = new THREE.Mesh(new THREE.SphereGeometry(50, 48, 24), mat);
  scene.add(dome);
  const pm = new THREE.PMREMGenerator(renderer);
  const rt = pm.fromScene(scene, 0.015);
  pm.dispose();
  dome.geometry.dispose(); mat.dispose();
  return rt;
}

