    material.attenuationColor.set(E.attenuationColor);
    material.attenuationDistance = Math.max(0.01, E.attenuationDistance);
    material.roughness = E.roughness;
    material.normalScale.setScalar(E.castRelief);
    material.clearcoat = E.clearcoat;
    material.clearcoatRoughness = E.clearcoatRoughness;
    material.specularIntensity = E.specular;
    material.envMapIntensity = E.envIntensity;
    material.sheen = E.sheen;
    material.sheenColor.set(E.sheenColor);
    material.sheenRoughness = E.sheenRoughness;
    material.iridescence = E.iridescence;
    material.iridescenceIOR = 1.3;
    material.iridescenceThicknessRange = [120, 420];
    material.side = (E.doubleSide && !s) ? THREE.DoubleSide : THREE.FrontSide;
    U.uRimStrength.value = E.rimStrength; U.uRimPow.value = E.rimPower; U.uRimLine.value = E.rimLine; U.uRimColor.value.set(E.rimColor);
    U.uGlow.value = E.glow; U.uGlowColor.value.set(E.glowColor);
    U.uGlowPulse.value = clamp(E.glowPulse, 0, 1); U.uGlowSpeed.value = clamp(E.glowSpeed, 0, 2);
    U.uCaustic.value = E.caustic; U.uCausticScale.value = E.causticScale; U.uCausticSpeed.value = E.causticSpeed;
    U.uShimmer.value = E.shimmer; U.uShimmerScale.value = E.shimmerScale;
    U.uThickFloor.value = E.thickFloor; U.uBgDisplay.value = clamp(E.bgDisplay,0,1); U.uBgAlpha.value = E.bgAlpha ? 1 : 0;
    U.uWallGlow.value = E.wallGlow; U.uWallColor.value.set(E.wallColor);
    U.uBrand.value = E.brandBlue; U.uBlueA.value.set(E.brandBlueColor); U.uBlueB.value.set(E.brandBlueDeep);
    U.uBlueGlow.value = E.brandBlueGlow; U.uBlueAbsorb.value = Math.max(0.02, E.brandBlueAbsorb);
